-- Replacement for CoA_SQL_02_REVIEW_Hunting_Rares_1558.sql
-- 2026-10-29 DBC/World DB/SRC re-audit, CURRENT SEASON *ONLY* conservative subset.
-- Original 1558 script was overly broad: 1203 criteria belong to category 15105
-- "Former Season Achievements"; only 355 to 16133 "Current Season Achievements".
-- This patch adds only 343 current-season criteria: all have the DBC's 1-kill
-- requirement, no extra DBC conditions/flags, creature rank 2 (Rare Elite) or
-- 4 (Rare), at least one current static creature spawn, no existing DB data.
-- The other 12 current-season criteria require review: 11 lack static spawns,
-- 1 refers to an elite-ranked (rank 1) rather than rare-ranked NPC.
-- NOTE: rank/spawn guards check the live World DB; source/event correctness
-- and hidden season activation rules are NOT provable from these assets.
-- SQL is additive, will not overwrite any existing criterion data.

DROP TEMPORARY TABLE IF EXISTS `coa_current_hunting_repair_ids`;
CREATE TEMPORARY TABLE `coa_current_hunting_repair_ids`
  (`criteria_id` INT UNSIGNED NOT NULL PRIMARY KEY,
   `creature_entry` INT UNSIGNED NOT NULL) ENGINE=InnoDB;




-- Actual insert: no existing rows overwritten, runtime rank/spawn guards.
START TRANSACTION;
SELECT `q`.`criteria_id`,0,0,0,''
FROM `coa_current_hunting_repair_ids` AS `q`
JOIN `creature_template` AS `t` ON `t`.`entry` = `q`.`creature_entry` AND `t`.`rank` IN (2,4)
WHERE NOT EXISTS
 (SELECT 1 FROM `achievement_criteria_data` AS `d` WHERE `d`.`criteria_id` = `q`.`criteria_id`)
AND EXISTS
 (SELECT 1 FROM `creature` AS `c` WHERE `c`.`id`=`q`.`creature_entry`);
COMMIT;

DROP TEMPORARY TABLE IF EXISTS `coa_current_hunting_repair_ids`;
